window.DIGEST.foryou.push(...[{"id": "2112538865894670780", "url": "https://x.com/GrokBotRadar/status/2112538865894670780", "text": "I just did it and this is a GAME CHANGER 🔥\n\nMy iPhone's Action Button is now a Grok Bot button. One press and I'm talking to my Bot 🤯\n\nIt's NOT under a \"Grok Bot\" option, so here's the exact path 👇\n\nSettings → Action Button\nSwipe to Shortcut\nPick Grok Bot → Start Voice Chat\n\nDo it NOW ⏰\n\nNeeds an iPhone with an Action Button (15 Pro or newer).\n\nSave this 🔖", "name": "Fan Grok Bot Radar", "handle": "GrokBotRadar", "avatar": "https://pbs.twimg.com/profile_images/2097879070243471366/LYMCnNQn_200x200.jpg", "likes": 38, "rts": 4, "replies": 7, "views": 2460, "ts": 1792503489, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112538829571948544/vid/avc1/1280x720/QtkGfV23a7Z4NQ2Z.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112538829571948544/vid/avc1/1920x1080/NhX9tiTTXT8sI6uc.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112538829571948544/img/YRK-iEhJ7YXTJxmR.jpg", "dur": 32}], "quote": {"id": "2112267346899255488", "url": "https://x.com/GrokBotRadar/status/2112267346899255488", "text": "THEY FINALLY DID IT 🚨\n\nYour iPhone's Action Button now talks straight to Grok Bot 🔥\n\nNo Grok app in the middle. Press it and you're talking to your Bot.\n\nLast week the hack was:\nAction Button → Grok voice → Grok hands the task to your Bots\n\nNow the middleman is gone 👋\n\nSet it up:\nSettings → Action Button → Grok Bot\n\nNeeds an iPhone with an Action Button (15 Pro or newer).\n\nDo NOT sleep on this one 🔖", "name": "Fan Grok Bot Radar", "handle": "GrokBotRadar", "avatar": "https://pbs.twimg.com/profile_images/2097879070243471366/LYMCnNQn_200x200.jpg", "likes": 136, "rts": 10, "replies": 12, "views": 20843, "ts": 1792438754, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112537933551206656", "url": "https://x.com/ginacostag_/status/2112537933551206656", "text": "Productivity isn't always about doing more.\n\nSpeakON makes it easy to capture thoughts with a single press of a button, using AI to turn voice recordings into clear, organized notes and actionable next steps.\n\nThe AI tools that stick are usually the ones that fit naturally into how we already live and work.", "name": "Gina Acosta", "handle": "ginacostag_", "avatar": "https://pbs.twimg.com/profile_images/1992357377534726144/t3e7Rv70_200x200.jpg", "likes": 49, "rts": 1, "replies": 6, "views": 17325, "ts": 1792503267, "media": [], "quote": {"id": "2112529279468835313", "url": "https://x.com/SpeakON_Global/status/2112529279468835313", "text": "we crushed a keyboard.\nits retirement party got a little out of hand.\n\nfor years, it was there for every email, every plan, every “just one more thing.” a loyal colleague. a very loud colleague.\n\nbut your ideas move faster than your fingers.\nand somewhere between knowing what you want to do and typing it all out, a quick task becomes another thing taking up your afternoon.\n\nmeet SpeakON AI Agent.\nstart with what you need, in your own words. less time behind a blinking cursor. more room to move things forward.\n\nthe keyboard had a good run.\nnow, let’s give your voice a turn.\n\nTHE LAST KEYSTROKE is here. watch the film, then tell us: what’s the first task you’d hand over?\nhttps://www.speakon.app/x\n\nDisclaimer: The calling feature is still in beta and will be available soon. All other Agent features are available now, with ongoing improvements.", "name": "SpeakON", "handle": "SpeakON_Global", "avatar": "https://pbs.twimg.com/profile_images/2034517364835004416/t7JRTf-G_200x200.jpg", "likes": 360, "rts": 27, "replies": 132, "views": 1088388, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/1280x720/1pVCcXx5_liTO3bD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/3840x2160/sZGYHjqRtzAtVYwR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515374826541056/img/Asq-ecx1B9r4GY89.jpg", "dur": 150}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112567410935177349", "url": "https://x.com/s_mohinii/status/2112567410935177349", "text": "Everyone building a voice app should see this.\n\nOne click, the model downloads, and it's ready on device. Bonus: the smallest Phonon carries an Apache 2.0 license.\n\nGitHub: https://github.com/gradium-ai/xn-ptts", "name": "Mohini Shewale", "handle": "s_mohinii", "avatar": "https://pbs.twimg.com/profile_images/2112570987942445057/uFC4eYlU_200x200.jpg", "likes": 45, "rts": 3, "replies": 2, "views": 22759, "ts": 1792510295, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112567303267397633/vid/avc1/1274x720/1ahiRTrJmEDn13VG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112567303267397633/vid/avc1/3188x1800/2VEopjPLEv1L0OHO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112567303267397633/img/XkG6PPr4CDVYHYX4.jpg", "dur": 30}], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189263, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112685796230639953", "url": "https://x.com/ericosiu/status/2112685796230639953", "text": "This is my COMPLETE AI operating system for business in 12 min.\n\nSend this to your agent and ask it to build what I have.\n\nThe setup:\n\n00:00 Why a scaling business needs AI operating models\n00:37 One human, a chief-of-staff bot, team bots in Slack\n02:17 Big changes come with three options and a pick\n03:05 Check every bot twice a weekday against its daily target\n05:17 Recruiting bots that shortlist before a human talks to anyone\n06:47 An AEO/SEO loop where what you publish shapes the next draft\n07:55 Safety rails before media files fill your storage\n10:14 The daily review: what needs me today\n11:18 Recording in, picked moments and drafted hooks out\n11:38 Sales-call briefs from the CRM and call history", "name": "ericosiu", "handle": "ericosiu", "avatar": "https://pbs.twimg.com/profile_images/1855481085595156480/wKSpzEkj_200x200.jpg", "likes": 26, "rts": 2, "replies": 4, "views": 2955, "ts": 1792538520, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112674915170013184/vid/avc1/640x360/zPaLDrYXSpCq_OIb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112674915170013184/vid/avc1/1280x720/iA-CUyeFTdgH5Xoa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112674915170013184/img/TjfcdX3m1gb4GQvx.jpg", "dur": 742}], "quote": {"id": "2109006664087240810", "url": "https://x.com/ericosiu/status/2109006664087240810", "text": "https://x.com/i/article/2108687058260918272", "name": "ericosiu", "handle": "ericosiu", "avatar": "https://pbs.twimg.com/profile_images/1855481085595156480/wKSpzEkj_200x200.jpg", "likes": 51, "rts": 4, "replies": 11, "views": 19539, "ts": 1791661346, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112695359541817807", "url": "https://x.com/Delphi_Digital/status/2112695359541817807", "text": "Grass founder @0xdrej explains how AI labs price training data.\n\n“We’ve got a specific benchmark that we want to improve a model on. What is the expected economic benefit of making the model better on that benchmark?”", "name": "Delphi Digital", "handle": "Delphi_Digital", "avatar": "https://pbs.twimg.com/profile_images/1546548223569010689/UIruFl-m_200x200.jpg", "likes": 23, "rts": 1, "replies": 6, "views": 6550, "ts": 1792540800, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112677829863247872/vid/avc1/1280x720/mibOG-3TBHKi8mDo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112677829863247872/vid/avc1/1920x1080/JXFwPzXuVZ5IIff9.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112677829863247872/img/tkAmlabwgMCvtimF.jpg", "dur": 46}], "quote": {"id": "2112668027489509877", "url": "https://x.com/YanLiberman/status/2112668027489509877", "text": "New Delphi Podcast with Andrej Radonjic @0xdrej, founder of Grass\n\nTo a website, Grass looks like normal users browsing. Behind it is millions of opted in residential nodes and a data platform that has delivered exabytes of web data to the frontier labs\n\nWe get into how AI flipped the hard part of search upside down. The index used to be the moat, and crawling was free. Now AI tooling makes the index cheap, while AI crawlers have pushed the web into blocking everything. The hard part is getting the page at all\n\nTraining data is already a profitable business for Grass with most of the top labs and multiple Mag 7 companies as customers. Crawling for that data also means mapping the entire internet, which is what puts Grass in a position to build search on top of it. Contents API is live, Search is next, and multimodal grounding follows\n\n00:00 Intro\n00:43 From Nuclear Physics to Web Scraping\n03:38 The Pandemic Signal Everyone Missed\n07:31 The Smart TV Proxy Scandal\n09:10 Why the Internet Is Blocking AI\n11:56 Training Data vs Live Data\n16:05 Mapping the Entire Internet\n18:03 Delivering Exabytes to AI Labs\n21:48 What AI Labs Really Pay For\n24:43 How Robots Learn From Web Video\n33:02 When Labs Change Direction\n35:57 One API Call for Any Website\n41:58 AI Flipped Search Upside Down\n47:03 Can the Network Keep Up?\n49:52 The Defense Tech of AI Data\n52:58 Why Data Is the Alpha\n57:08 Why AI Labs Won’t Buy Slop\n59:17 The Metric That Matters Most\n01:02:35 The $100 Billion Data Market\n01:05:07 Who Actually Owns Grass\n01:08:18 What a Real Moat Looks Like\n01:13:16 What Happens Next\n\nDisclosure. Delphi Ventures holds $GRASS\n\nFull episode", "name": "Yan Liberman", "handle": "YanLiberman", "avatar": "https://pbs.twimg.com/profile_images/1735359758993936384/9s72UmFc_200x200.jpg", "likes": 78, "rts": 19, "replies": 9, "views": 13927, "ts": 1792534283, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112644606395375616/vid/avc1/1280x720/w0GZLAYrXl7NmtDJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112644606395375616/vid/avc1/3840x2160/gnF365zTDpIlWBuT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112644606395375616/img/VkgN0z5VUdjiiDlG.jpg", "dur": 4542}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112611632304079231", "url": "https://x.com/robrtcode/status/2112611632304079231", "text": "this is terrifying…", "name": "robert.", "handle": "robrtcode", "avatar": "https://pbs.twimg.com/profile_images/2095698934278537218/zFRwP03U_200x200.jpg", "likes": 50, "rts": 0, "replies": 0, "views": 726, "ts": 1792520838, "media": [], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1849470, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112240710485467435", "url": "https://x.com/MTSlive/status/2112240710485467435", "text": "SITUATION EXPLAINED: Anthropic just put 5% of its shares, nearly $50 billion, toward what could become AI-funded UBI.\n\n• The fund is wholly owned by Anthropic, and the board can add 2% more for every 50% rise in Anthropic's value above a set baseline\n• With existing pledges, including the cofounders' 80% of their equity, about 20% of Anthropic is pledged to the public good, close to $200B at its $965B valuation\n• It could fund large donations to traditional nonprofits or \"direct distributions to specific populations,\" a give-directly, UBI-style approach\n• Anthropic already committed $200M to studying AI's impact on jobs and says the fund allows \"bolder approaches\"\n\n@schisofrenia: \"We can start doing longitudinal studies, like if you give to a specific population, say, in the US or in an impoverished town in the US or outside of the US, then you can start to do longitudinal studies on how that affects people.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 126, "rts": 6, "replies": 9, "views": 18031, "ts": 1792432403, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112240602553479168/vid/avc1/640x360/5w564HNjpHRV08yd.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112240602553479168/vid/avc1/1280x720/Ae1hbO3dQF-6daCm.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112240602553479168/img/iEblmlw0gjJmkYI2.jpg", "dur": 287}], "quote": {"id": "2111881963657412903", "url": "https://x.com/AnthropicAI/status/2111881963657412903", "text": "We’re committing a portion of Anthropic’s shares to the Anthropic Public Benefit Fund, a new wholly owned entity dedicated entirely to the public benefit.\n\nIt will start off with 5% of our shares. For every 50% increase in the company’s value over a set baseline, we can contribute up to an extra 2%, subject to our board’s discretion.\n\nIn total, this means that roughly 20% of Anthropic’s shares are committed to the public good. Our co-founders have already pledged to donate 80% of their equity, and around half our employees are donating a portion of their equity as part of a donation matching program we’ve run since our founding.\n\nIn the post below, we share more details about our new fund.\n\nhttps://www.anthropic.com/news/public-benefit-fund", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 21479, "rts": 1737, "replies": 2282, "views": 7474721, "ts": 1792346871, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112247100465414406", "url": "https://x.com/0x_rody/status/2112247100465414406", "text": "It is becoming f*cking dangerous  \n\nA 27-year-old dev from China just ran 300 Grok agents in parallel and hooked them to a Jev verification layer so none of them could bullshit him  \n\nHe opens the live dashboard: \n- 300 agents writing and checking at the same time \n- Every output verified against the source in ~100 ms \n- Three passes over 100 company profiles → zero errors left \n- Everything dumped straight into an Obsidian vault\n\nThe trick is the split: one model does the work, a cheaper one decides if the claim is actually true. The loop doesn’t stop until everything checks out  \n\nAn analyst team would bill weeks for this. He got it in one run  \n\nJev + Grok Bots swarm setup that keeps circulating. Bookmark the full breakdown below:", "name": "rody", "handle": "0x_rody", "avatar": "https://pbs.twimg.com/profile_images/2041947351120572416/4IBmZ3QT_200x200.jpg", "likes": 99, "rts": 14, "replies": 9, "views": 12452, "ts": 1792433927, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112246655265202176/vid/avc1/1280x720/b2Ib_ZmfPOlnb1XL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112246655265202176/vid/avc1/1920x1080/xTldXuSx8WGVAq5M.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112246655265202176/img/zlmGlMH-wZTaxnOd.jpg", "dur": 15}], "quote": {"id": "2111505949131227180", "url": "https://x.com/maestrooth/status/2111505949131227180", "text": "https://x.com/i/article/2111348714757378048", "name": "maestro", "handle": "maestrooth", "avatar": "https://pbs.twimg.com/profile_images/2090164287595741184/eIyfgPau_200x200.jpg", "likes": 92, "rts": 12, "replies": 3, "views": 94934, "ts": 1792257222, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112551917838569615", "url": "https://x.com/niklaslenz_ai/status/2112551917838569615", "text": "256 GB Mac class: Qwen3.8-Flash-Next on my Mac Studio M5 Ultra built a voxel world in 58 minutes.\n\noMLX 0.7.0 by @jundotkim, oQ4e quant with MTP.\nAgent: Qwen Code 0.25.2, thinking on, model-card sampling.\nOne prompt, one try, no help.\n\nBrowser check: 8.5/10\nTokens written: 225,892\nSpeed benchmark: 152 tok/s decode (separate run, thinking off)\n\nQwen Code's own loop guard ended the run at 58 min, the last file counts. The browser check was re-run on a DGX Spark because the first checker had too few CPUs; the page files are unchanged.\n\nI'm disappointed with this world, and I've seen much better results from this model on a Spark.\n\nExact command and raw output: https://niklaslenz.com/v2/qwen38-flash-next-mac-omlx-mtp/", "name": "Niklas", "handle": "niklaslenz_ai", "avatar": "https://pbs.twimg.com/profile_images/2108625696088113152/uVudOEyp_200x200.jpg", "likes": 45, "rts": 1, "replies": 6, "views": 3761, "ts": 1792506601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112548197914599424/vid/avc1/1280x720/X-3ckFDYhKkfq3TF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112548197914599424/vid/avc1/1920x1080/-3zZaV67rTcNP_c8.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112548197914599424/img/QzjH6w0ZgWCH60Po.jpg", "dur": 37}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112584088418992501", "url": "https://x.com/tec_aryan/status/2112584088418992501", "text": "kinda impressive what 1.3B can do with a document-specific design.\nOXR leads olmOCR-Bench, OmniDocBench and DocParsingBench, covering formulas, complex tables and chemical structures.\n\nThey measured 1.43× PaddleOCR-VL-1.6 throughput on 100 OmniDocBench pages with one RTX PRO 6000.\n\nRSI shapes post-training. Recognition and content-aware reading order run in parallel, while layout is independent and replaceable.\n\nthe architecture deserves a look alongside the scores. so does its speed lead over every open-source parser.\n\nhttps://github.com/SoMarkAI/OXR", "name": "Aryan Rakib", "handle": "tec_aryan", "avatar": "https://pbs.twimg.com/profile_images/1753625702803611648/d91sPS71_200x200.jpg", "likes": 15, "rts": 11, "replies": 3, "views": 33081, "ts": 1792514271, "media": [], "quote": {"id": "2112574994152636502", "url": "https://x.com/somarkai/status/2112574994152636502", "text": "Beyond OCR. Meet OXR.\nOnly 1.3B. Open source.\n\n#1 on olmOCR-Bench, OmniDocBench & DocParsingBench🏆\n#1 in parsing speed among open-source models⚡\n\nRSI-powered. A first in document parsing.\nTurn documents into Agent-Friendly data.\n\nIf OXR helps, give us a star on GitHub! 🌟", "name": "SoMark", "handle": "somarkai", "avatar": "https://pbs.twimg.com/profile_images/2054830841197690880/72QHhpxV_200x200.jpg", "likes": 64, "rts": 15, "replies": 19, "views": 235906, "ts": 1792512103, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112574131791097857/vid/avc1/720x720/sb4cgnPfueTkA0vb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112574131791097857/vid/avc1/1200x1200/ohWAOZCkHsVrYIVo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112574131791097857/img/WA95Dj7H23zc6QHc.jpg", "dur": 18}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112387276458139709", "url": "https://x.com/arigameplays/status/2112387276458139709", "text": "Gracias por hoy 😀😀😀", "name": "ARIA", "handle": "arigameplays", "avatar": "https://pbs.twimg.com/profile_images/2077855067047112704/YBwk3pu9_200x200.jpg", "likes": 13920, "rts": 682, "replies": 169, "views": 580766, "ts": 1792467347, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112370267829780481/vid/avc1/540x540/7BvUSJbLGnwlaO69.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112370267829780481/vid/avc1/720x720/zqzJ_i2OpG_5AXGc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112370267829780481/img/tQ0jJt8URnStrQmE.jpg", "dur": 6}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112547606970921282", "url": "https://x.com/hasantoxr/status/2112547606970921282", "text": "The next growth hire at a 10-person company is going to be a budget cap, not a person.", "name": "Hasan Toor", "handle": "hasantoxr", "avatar": "https://pbs.twimg.com/profile_images/2112453255959920640/W-1qt_Wk_200x200.jpg", "likes": 39, "rts": 3, "replies": 6, "views": 10915, "ts": 1792505573, "media": [], "quote": {"id": "2112544721839284632", "url": "https://x.com/zaviagent/status/2112544721839284632", "text": "Introducing Zavi.\n\nGrowth on autopilot. ✨\n\nGive it your website. Zavi finds what’s holding your growth back, then runs your ads, SEO, social posts, and emails.", "name": "Zavi", "handle": "zaviagent", "avatar": "https://pbs.twimg.com/profile_images/2112544960159580160/RjsBsJt8_200x200.jpg", "likes": 73, "rts": 8, "replies": 29, "views": 30970, "ts": 1792504885, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112540679570370560/vid/avc1/1280x720/Sem35ZOWXmZf6oms.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112540679570370560/vid/avc1/1920x1080/rilFa6rZt0s_5Fx_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112540679570370560/img/Qnxh33lSvreWzGv6.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112498393956454796", "url": "https://x.com/AiEvolutio58513/status/2112498393956454796", "text": "Sam Altman explains why the AI field, OpenAI included, got jobs wrong:\n\n\"If we could go back to 2019 and show people our latest model, not only would they say that it's AGI, they would say that the economy would have had it completely upended.\"\n\n\"And that has not happened. And I think just from a kind of like intellectual humility point, anytime you're that wrong and that confident, which I think we were as a field, you have to update.\"\n\nWhat he got wrong:\n\n1. \"AI is just very jagged. It's like super human genius in some ways, like dumb toddler in others.\"\n2. \"People have so far extremely complementary skills to AI.\"\n3. \"Somehow most people seem to still really prefer interacting with a human.\"\n\nSame story with coders: \"A year ago, people said software engineers are cooked, it's done, it's over. That didn't happen.\"\n\nEven for his own job, he says people \"don't really want an AI CEO.\"\n\nInterested in AI?\n\nFollow @AiEvolutio58513 and never fall behind.\n\nI track ChatGPT, Claude, and every tool quietly changing how we work and create, then hand you the tested signals.", "name": "AI Evolution", "handle": "AiEvolutio58513", "avatar": "https://pbs.twimg.com/profile_images/2051404095026810880/ojNDixza_200x200.png", "likes": 30, "rts": 12, "replies": 2, "views": 2737, "ts": 1792493840, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112498313111248896/vid/avc1/1280x720/XM4Tdnw8JLFtBenS.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112498313111248896/vid/avc1/1920x1080/73P4o53Mmp6PGhLw.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112498313111248896/img/9pOCQkSrAc8jgqn0.jpg", "dur": 83}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112261368288293179", "url": "https://x.com/kimmonismus/status/2112261368288293179", "text": "1/ Video Rebirth (@video_rebirth) just open-sourced HyperFlow, a speed-up for the MiniMax H3 video model.\n\nIt cuts generation from 49 steps to 8 and runs about 3x faster, with sound generated alongside the video.\n\nWe tested it on three very different prompts. Here's how it held up.", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 103, "rts": 5, "replies": 16, "views": 13922, "ts": 1792437328, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112261331919515648/vid/avc1/1270x720/XzUrwTIsxkDhQIjG.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112261331919515648/vid/avc1/1904x1080/Zbkdq9eAcK87sOau.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112261331919515648/img/Glt8g90-X6jFZ70V.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112584064540844143", "url": "https://x.com/graycrawford/status/2112584064540844143", "text": "it appears my squinting simulator is working 👀\n\nwe all love wave optics, naked-eye interference, eyelash diffraction right", "name": "gray ❄️🫧", "handle": "graycrawford", "avatar": "https://pbs.twimg.com/profile_images/1704165425355825152/UCBk-jZk_200x200.jpg", "likes": 6831, "rts": 453, "replies": 140, "views": 216881, "ts": 1792514265, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112582325175558147/vid/avc1/1164x720/5beKIYbCg0GgUv-F.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112582325175558147/vid/avc1/3492x2160/lOQTWkhUE1SUs_CB.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112582325175558147/img/luC0N0EWfbn2ldVD.jpg", "dur": 6}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112501351968055302", "url": "https://x.com/TechCrunch/status/2112501351968055302", "text": "Meeting note-taking tool http://spr.ly/6017BHTo6h announced on Tuesday that it has raised $320 million from General Catalyst’s Customer Value Fund (CVF), which provides capital to startups without diluting equity and gets returns on the results of marketing spend.\nhttp://spr.ly/6019BHToBB", "name": "TechCrunch", "handle": "TechCrunch", "avatar": "https://pbs.twimg.com/profile_images/1096066608034918401/m8wnTWsX_200x200.png", "likes": 29, "rts": 4, "replies": 14, "views": 16743, "ts": 1792494545, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112279612340232483", "url": "https://x.com/Flandermaxx/status/2112279612340232483", "text": "WHOEVER LEAKED THIS JEV SIGNAL LOOM SHOULD BE WRITING THE WHITE PAPER\n\nI thought asking an agent a question meant prompting the model, waiting for a sentence, and parsing it to figure out what it just said.\n\nApparently not.\n\nThis loom's setup is much more interesting:\n\n→ CHOICE head returns one label from an ordered set in 3ms, nothing else allowed, no free-form string on retry\n→ SCORE head ranks the same set by criterion, one score per item, no \"explain the ranking\" prose anywhere\n→ NOUL head answers yes/no in 4ms with a confidence, below the gate floor drops straight to human review\n→ ONE STATE merges the three heads at 1,257 answers per second, 60 bundles 600 threads, no raw text crosses the gate\n→ CODE acts on the gated state deterministically, flags 5 action drifts above the baseline the author never caught\n\nso you get:\n\nChoices labeled. Scores ranked. Nouls floored. Actions deterministic.\n\nthe interesting part isn't making the model smarter.\nit's giving every question a head whose output type the code can trust.\n\nInstead of parsing one freeform answer per decision at Claude prices, you weave three typed heads at $0.42 per 10,000 decisions, 256ms median, and let the gate drop anything under 0.85.\n\nWeave the heads. Gate the state. Act in code.", "name": "Flandermaxx", "handle": "Flandermaxx", "avatar": "https://pbs.twimg.com/profile_images/2096231413234515968/1PYpYwc6_200x200.jpg", "likes": 82, "rts": 13, "replies": 9, "views": 3961, "ts": 1792441678, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112279091944542208/vid/avc1/720x900/NuyRwk-IEdbqwceC.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112279091944542208/vid/avc1/1080x1350/C4E3-CQUK0Ea4R1W.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112279091944542208/img/EnXFKQd6EJexlFL3.jpg", "dur": 27}], "quote": {"id": "2100984487802708306", "url": "https://x.com/0xCodila/status/2100984487802708306", "text": "Jev is the \"Internet\" moment for the AI industry\n\nIt tells your agents and LLMs what to do next, in milliseconds and at almost zero cost\n\nIf you set it up correctly, you will have the AI engineer’s stack for 2028\n\nIn this article, I show you how https://x.com/i/article/2077744776565149697", "name": "codila", "handle": "0xCodila", "avatar": "https://pbs.twimg.com/profile_images/2064453666661441536/nj8n8Mei_200x200.jpg", "likes": 3485, "rts": 436, "replies": 94, "views": 2284715, "ts": 1789748710, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112596613319537073", "url": "https://x.com/GeniusGTX/status/2112596613319537073", "text": "95% of your B2B market isn't ready to buy right now, and most founders only sell to the other 5%.\n\nAlex Hormozi explained why that leaves most of the money on the table:\n\n\"Let's say 100 people. So you have 100 people and you say, 'Hey, come buy my thing.' Maybe you get one of those people to raise their hand.\"\n\n\"But if we have those same hundred people and we say, 'Hey, you don't have to buy anything. I just want to help you out.' And then after we help them out, we say, 'Hey, now do you want to buy something?' ... we might get three to five times that amount of people.\"\n\n\"You're actually not going to get more traffic. You're just going to convert a higher percentage of it.\"\n\nCame across this article today. Pierre has grown 2 companies to $1M with content and social selling.\n\nHis playbook runs two plans at the same time:\n\n- Passive buyers (95%): open content, a little gated content, and showing up where they already are\n- Active buyers (5%): case studies and demos, warm outbound to anyone who shows a signal, a clear sales process\n- Both lead to a landing page that converts and an entry offer that's easy to say yes to\n\nWorth reading in full:", "name": "GeniusThinking", "handle": "GeniusGTX", "avatar": "https://pbs.twimg.com/profile_images/2050658876195065856/wXZMLbh2_200x200.jpg", "likes": 16, "rts": 10, "replies": 2, "views": 3165, "ts": 1792517257, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112596535322296320/vid/avc1/1280x720/ltwgBeYPAv52Vtth.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112596535322296320/vid/avc1/1920x1080/p7UyiKQH0ms0_p17.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112596535322296320/img/exfufpc_3YssHvew.jpg", "dur": 99}], "quote": {"id": "2112582208318054427", "url": "https://x.com/PierreHerubel/status/2112582208318054427", "text": "How to actually find B2B clients:\n\nI've grown 2 companies to $1M with content + social selling, including my current agency, ContentPath. Here's the playbook we now run for our B2B clients.\n\nIt's built on one split. About 95% of your market isn't ready to buy right now, and 5% is. You need a plan for both, running in sync:\n\n1/ Passive buyers (95%): get known before they need you\n\nThey're keeping up with their industry and their job. So be the one they learn from:\n\n- Open content for discovery: podcasts, video, and posts from your founder and team\n- Gated content for deeper expertise: webinars, industry reports, a private community. Keep it to about 1% of what you publish, and make it excellent.\n- Social engagement where they already are: events, comments and DMs, outside communities\n\n2/ Active buyers (5%): reach them before a competitor does\n\nBeing ready to buy doesn't mean they'll reach out. So don't wait for them:\n\n- Conversion content to turn your audience into leads: case studies, white papers, demos\n- Warm outbound to start conversations: message anyone who downloads a report, signs up for a webinar or visits your pricing page, and run ABM on your larger accounts. The warmer the signal, the more direct the message.\n- An active sales process to close deals faster: discovery calls, follow-ups by email and DM, a clear closing flow\n\n3/ Both plans lead to 2 things\n\n- A website or landing page that converts\n- An entry offer that's easy to say yes to (build this one first)\n\nB2B founders have paid me to teach them this playbook. Now it's free for everyone in the article below, including how to run it on LinkedIn.\n\n(bookmark for later)", "name": "Pierre", "handle": "PierreHerubel", "avatar": "https://pbs.twimg.com/profile_images/1799519827784036352/QuhIc6Jx_200x200.jpg", "likes": 7, "rts": 3, "replies": 0, "views": 3570, "ts": 1792513822, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFmTiOboAESyKM.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112414152664998173", "url": "https://x.com/HermesWatcher/status/2112414152664998173", "text": "Absurd.\n\nHermes agents built this entire game out of code. Not a single art file.\n\nEvery sword, skeleton, stone wall, sound effect and note of music is generated the moment you press play.\n\n▸ A dark fantasy dungeon crawler in the style of Diablo\n▸ 107,000 lines of code across 142 modules\n▸ Built by Hermes subagents working in parallel, up to six at once\n▸ Crypts, moors and a town, all generated\n▸ 10 abilities, a skill tree and multi-phase boss fights\n▸ A music score that adapts as you play\n▸ Runs in your browser, MIT licensed\n\nOne person directing. A team of Hermes agents doing the rest.\n\nLuke killed it here 🔥", "name": "Hermes Release Watch", "handle": "HermesWatcher", "avatar": "https://pbs.twimg.com/profile_images/2079058210410094592/t-ZASzl0_200x200.jpg", "likes": 72, "rts": 2, "replies": 7, "views": 5022, "ts": 1792473755, "media": [], "quote": {"id": "2112361784137113988", "url": "https://x.com/iamlukethedev/status/2112361784137113988", "text": "This entire game has zero asset files 💀\n\nNo textures\nNo meshes\nNo monster models\nNo images\nNo audio files\n\nThe Ninth Vigil is a Diablo-inspired dark fantasy action RPG where everything you see and hear is generated in code when you press play\n\nAnd the crazier part?\n\nIt was built by @NousResearch Hermes agents\n\nThe world, enemies, combat, effects, sounds, UI, all of it\n\nRuns directly in your browser\n\nFree. Open source.\n\nI asked Hermes to build a game\n\nApparently it decided it didn’t need an art folder 😂\n\nhttps://x.com/iamlukethedev/status/2112100287599284537?s=20", "name": "Luke The Dev", "handle": "iamlukethedev", "avatar": "https://pbs.twimg.com/profile_images/1978432948836749312/hfXIZ_5S_200x200.jpg", "likes": 541, "rts": 34, "replies": 45, "views": 53123, "ts": 1792461269, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112359097958092800/vid/avc1/1280x720/pwAmTC7F3j6PI0-p.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112359097958092800/vid/avc1/1920x1080/pbwIutZmLBgfqi2k.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112359097958092800/img/rmvIzY9ieGZtGjiG.jpg", "dur": 51}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112621498384941333", "url": "https://x.com/maestrooth/status/2112621498384941333", "text": "SpaceXAI lead engineer (ex-Cursor):  \n\n\"99% of people are still typing into a chat window. 1% have already hired a team  \n\nI run 6 bots. My Chief of Staff wakes me at 6am with my entire day, and my travel bot delegates to my flight bot and my hotel bot while I sleep\"  \n\nChat → Copilot → GrokBot → Bot Teams → Self-Improving Systems  \n\nPrompting was the old workflow. Hiring is the next one  \n\nRead how to hire your first Grok Bot in the article below ↓", "name": "maestro", "handle": "maestrooth", "avatar": "https://pbs.twimg.com/profile_images/2090164287595741184/eIyfgPau_200x200.jpg", "likes": 32, "rts": 1, "replies": 6, "views": 1618, "ts": 1792523190, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112621090442813440/vid/avc1/720x936/BbQ1HztGXtf22jfh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112621090442813440/vid/avc1/1080x1404/VDgNR47VfSqROJmC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112621090442813440/img/dnWBOCVBCTdxl0Uf.jpg", "dur": 26}], "quote": {"id": "2111505949131227180", "url": "https://x.com/maestrooth/status/2111505949131227180", "text": "https://x.com/i/article/2111348714757378048", "name": "maestro", "handle": "maestrooth", "avatar": "https://pbs.twimg.com/profile_images/2090164287595741184/eIyfgPau_200x200.jpg", "likes": 92, "rts": 12, "replies": 3, "views": 94932, "ts": 1792257222, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112718669059178555", "url": "https://x.com/mandylu/status/2112718669059178555", "text": "yeah, Bach was the best to ever do it", "name": "Mandy Lu", "handle": "mandylu", "avatar": "https://pbs.twimg.com/profile_images/1984815627157323779/Oin3BDAz_200x200.jpg", "likes": 20, "rts": 0, "replies": 7, "views": 1301, "ts": 1792546357, "media": [], "quote": {"id": "2112600761762717997", "url": "https://x.com/elonmusk/status/2112600761762717997", "text": "Johann Sebastian Bach is the Shakespeare of music. Best there ever was.", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 48271, "rts": 3355, "replies": 5558, "views": 5335138, "ts": 1792518246, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112672068915306546", "url": "https://x.com/maxwell_lenoir/status/2112672068915306546", "text": "Speculative decoding usually needs tuning for each setup. \n\nEagle Corp's new EAGLE-4 takes a different route: a single open-source drafter that adjusts to batch size, hardware and workload, keeping the target model's outputs unchanged.\n\nWorth benchmarking", "name": "max", "handle": "maxwell_lenoir", "avatar": "https://pbs.twimg.com/profile_images/2098765140254490626/QmyZ5sxn_200x200.jpg", "likes": 9, "rts": 5, "replies": 8, "views": 262, "ts": 1792535247, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVG4DGrWUAAWIeo.jpg?name=orig"}], "quote": {"id": "2112660683670323531", "url": "https://x.com/EagleCorp/status/2112660683670323531", "text": "EAGLE-4 is here.\n\nFrom EAGLE-1 to EAGLE-3, we’ve kept making inference faster. \n\nEAGLE-4 is our fastest yet.\n\n961.6 tokens/s on @Alibaba_Qwen’s Qwen3.8-27B with TokenSpeed (BF16, 4× @NVIDIA B300, TP4, one request, T=0).\n\nGithub: https://github.com/eagle-hq/EAGLE-4", "name": "Eagle", "handle": "EagleCorp", "avatar": "https://pbs.twimg.com/profile_images/2057212553915248640/zgJtC7pK_200x200.jpg", "likes": 4170, "rts": 519, "replies": 376, "views": 1080307, "ts": 1792532532, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1280x720/-10uYli5CGPejFwB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1920x1080/6UlvgUxk_hy6qXRU.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112660579664187392/img/oFNlAedcp82x1A_3.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112669621216244034", "url": "https://x.com/urdeaintech/status/2112669621216244034", "text": "512 concurrent requests hit the server\neagle-4 walking through like it’s nothing\n\nthe paper reports 1.70x over DFlash 2 at that load btw\n\nhttps://github.com/eagle-hq/EAGLE-4", "name": "Samuel Urdea", "handle": "urdeaintech", "avatar": "https://pbs.twimg.com/profile_images/2092899894218416128/ZypwJ5s7_200x200.jpg", "likes": 18, "rts": 2, "replies": 8, "views": 1136, "ts": 1792534663, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVG10IYXkAA6z2n.mp4", "hd": "https://video.twimg.com/tweet_video/HVG10IYXkAA6z2n.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVG10IYXkAA6z2n.jpg", "dur": 0}], "quote": {"id": "2112660683670323531", "url": "https://x.com/EagleCorp/status/2112660683670323531", "text": "EAGLE-4 is here.\n\nFrom EAGLE-1 to EAGLE-3, we’ve kept making inference faster. \n\nEAGLE-4 is our fastest yet.\n\n961.6 tokens/s on @Alibaba_Qwen’s Qwen3.8-27B with TokenSpeed (BF16, 4× @NVIDIA B300, TP4, one request, T=0).\n\nGithub: https://github.com/eagle-hq/EAGLE-4", "name": "Eagle", "handle": "EagleCorp", "avatar": "https://pbs.twimg.com/profile_images/2057212553915248640/zgJtC7pK_200x200.jpg", "likes": 4166, "rts": 519, "replies": 376, "views": 1080307, "ts": 1792532532, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1280x720/-10uYli5CGPejFwB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1920x1080/6UlvgUxk_hy6qXRU.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112660579664187392/img/oFNlAedcp82x1A_3.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112602206062919778", "url": "https://x.com/YahooFinance/status/2112602206062919778", "text": "If OpenAI and Anthropic don’t go public, where should investors put their money? \n\nKristen Kelly, co-founder of @thewallstskinny, said popular alternatives like utility stocks are “still AI.” @AmyWuSilverman compared that kind of diversifying to a meme of “the surge protector plugged into itself.\"\n\n\"All these things are still part of the AI trade,\" Silverman added.", "name": "Yahoo Finance", "handle": "YahooFinance", "avatar": "https://pbs.twimg.com/profile_images/1852386668646379524/H-Kso-3l_200x200.png", "likes": 22, "rts": 4, "replies": 8, "views": 11817, "ts": 1792518590, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112602064664612864/vid/avc1/1280x720/GOICDykb--jv1WOP.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112602064664612864/vid/avc1/1920x1080/hi8Q2Byheiy1KP7T.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVF4gnGWYAAOEI1.jpg", "dur": 130}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112557955090624865", "url": "https://x.com/lesviancake/status/2112557955090624865", "text": "better coding support and efficient inference in one model sounds useful. \n\nlooking forward to seeing how Ornith-1.5-122B handles practical development work.", "name": "Lesvi Cake", "handle": "lesviancake", "avatar": "https://pbs.twimg.com/profile_images/2014230469597147136/6HTA5Omb_200x200.jpg", "likes": 21, "rts": 1, "replies": 16, "views": 3545, "ts": 1792508040, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086709, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112333096792318461", "url": "https://x.com/arena/status/2112333096792318461", "text": "We just put Muse Wonder and Muse Wonder Full by @AIatMeta to the test across 3D scenes, animated HTML clips, and several website builds.\n\nWatch @petergostev compare both models against Claude Opus 5.5, Sonnet 5.5, Fable 5.1, GPT-6.1 Sol, GPT-6 Astra, and Gemini 4 Argon.\n\nhttps://www.youtube.com/watch?v=limOMzWqoeU", "name": "Arena.ai", "handle": "arena", "avatar": "https://pbs.twimg.com/profile_images/2017015061454438400/iNKfXZ_I_200x200.jpg", "likes": 63, "rts": 2, "replies": 23, "views": 17002, "ts": 1792454430, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112590942179868768", "url": "https://x.com/MikelEcheve/status/2112590942179868768", "text": "A TTS model that runs on your phone. No GPU, no internet.\n\nGradium just open-sourced Phonon.\n\nThe 31m one is 64 MB and gets 1.7% word error rate on hard text like phone numbers and emails. Kokoro gets 3.5%.\n\nOne multilingual version covers English, French, German, Spanish and Portuguese.\n\nHere's what switching languages sounds like.", "name": "Mikel", "handle": "MikelEcheve", "avatar": "https://pbs.twimg.com/profile_images/1993076668768923648/17ba6863_200x200.jpg", "likes": 28, "rts": 6, "replies": 2, "views": 1163, "ts": 1792515905, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590917844570112/vid/avc1/640x360/xYXpBPt16bHVnU38.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590917844570112/vid/avc1/1280x720/i4KJXbp54ZmADrjx.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590917844570112/img/0M9k98rLCeKCj-6r.jpg", "dur": 13}], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112601261493407843", "url": "https://x.com/TechByMarkandey/status/2112601261493407843", "text": "One AI agent helped create marketing content that generated 300K+ views in just 24 hours.\n\nPedro used Muse, an AI agent on WhatsApp, to market his quit-drinking app.\n\nHere’s what it did:\n- Researched viral TikTok content and studied what made people keep swiping.\n- Turned the best ideas into slideshows and created multiple versions.\n- Improved the content based on Pedro’s feedback.\n- Organized and scheduled posts through Postiz, with a maximum of 2 posts per day.\n\nPedro only had to review and approve the final content calendar.\n\nAI agents are moving beyond answering questions. They can now research, create, and schedule content while you focus on growing your business.", "name": "Markandey Sharma", "handle": "TechByMarkandey", "avatar": "https://pbs.twimg.com/profile_images/2108632613602942976/O07ORNDX_200x200.jpg", "likes": 19, "rts": 2, "replies": 12, "views": 13581, "ts": 1792518365, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112601231097286656/vid/avc1/1274x720/wV-CLiJcRnU9ihW2.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112601231097286656/vid/avc1/1912x1080/Jc7YcZftKiZhLrTL.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112601231097286656/img/Yqhv9YhP2RmqGvyG.jpg", "dur": 14}], "quote": {"id": "2112574200707727786", "url": "https://x.com/PerezHatesAI/status/2112574200707727786", "text": "https://x.com/i/article/2107937586874331136", "name": "Pedro Pérez", "handle": "PerezHatesAI", "avatar": "https://pbs.twimg.com/profile_images/2090113883721678848/x0-_oaUT_200x200.jpg", "likes": 87, "rts": 8, "replies": 18, "views": 41454, "ts": 1792511913, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112595782985830853", "url": "https://x.com/aniketh_iyengar/status/2112595782985830853", "text": "At a time when many seek real impact from AI, I'm excited by our team's progress! Moving beyond in-silico benchmarks to practical biology and clinical applications is a major leap. With Omnii-1, we're already seeing strong performance w/ minimal tuning. Excited for what's next!", "name": "Aniketh Iyengar", "handle": "aniketh_iyengar", "avatar": "https://pbs.twimg.com/profile_images/1783738515702120448/W5BzszbD_200x200.jpg", "likes": 33, "rts": 3, "replies": 4, "views": 1080, "ts": 1792517059, "media": [], "quote": {"id": "2112580926651904379", "url": "https://x.com/exnx/status/2112580926651904379", "text": "Introducing Omnii-1, our most powerful genome language model, and a major step toward general biological intelligence\n\nIn a world first, Omnii-1 designed the first AI-generated bacteriophages to be administered to a human patient with an antibiotic-resistant infection under compassionate use", "name": "Eric Nguyen", "handle": "exnx", "avatar": "https://pbs.twimg.com/profile_images/1640862340517335040/qcpMIN_b_200x200.jpg", "likes": 925, "rts": 163, "replies": 95, "views": 460821, "ts": 1792513517, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1280x720/o7F7SW5uTq0n6Cki.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1920x1080/PQ3lBUGHdIKOCD3U.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112578540013330432/img/iIkujuAjkAiQkxwh.jpg", "dur": 155}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112619265719456119", "url": "https://x.com/Shelpid_WI3M/status/2112619265719456119", "text": "REA × Kimi K3 is where reverse engineering starts getting dangerous.\n\nThe biggest bottleneck is asking one model to keep an entire app in its head.\n\nREA changes how the work gets done.\n\nInstead of throwing a codebase at one agent, it splits the investigation across a swarm.\n\nMap the app → Assign focused tasks → Trace connections → Cross-check findings → Reconstruct the architecture.\n\nEach agent investigates a smaller piece. Together, they connect the pieces into a bigger picture.\n\nNo single agent has to understand everything for the swarm to understand how it fits together.\n\nThat’s what makes REA × K3 interesting.\n\nThe question shifts from “How much code can one model remember?” to “How well can the agents investigate and compare what they find?”\n\nFull course in the article below.", "name": "Shelpid.WI3M", "handle": "Shelpid_WI3M", "avatar": "https://pbs.twimg.com/profile_images/1740494620033785856/E7xDLazn_200x200.jpg", "likes": 27, "rts": 3, "replies": 5, "views": 2244, "ts": 1792522658, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112619202645307392/vid/avc1/720x720/Ltdw0uri1CbnFHb-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112619202645307392/vid/avc1/2160x2160/EXfOjljxfPrgVAYm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112619202645307392/img/W0yv3QA1o1-lspZK.jpg", "dur": 35}], "quote": {"id": "2110357188946370778", "url": "https://x.com/0xRicker/status/2110357188946370778", "text": "https://x.com/i/article/2109999710261895168", "name": "Ricker", "handle": "0xRicker", "avatar": "https://pbs.twimg.com/profile_images/2014389251580813312/ke_dI_-z_200x200.jpg", "likes": 158, "rts": 16, "replies": 11, "views": 105819, "ts": 1791983337, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.15, "thread": [], "tier": "worth"}, {"id": "2112456999782785030", "url": "https://x.com/surim0n/status/2112456999782785030", "text": "tried one shotting Korean immigration (arrival) forms with several agents as my flight left the tarmac\n\nonly one agent came through \n\nDot failed \nHermes’ & Openclaw failed \nMuse horribly failed \n\nDot, Hermes’ and openclaw came close but refused to do anything sensitive like submitting forms. This guardrail only started in the gpt6 era. \n\nMuse kept saying it couldn’t find certain buttons to click\n\ncodex w/ 5.6 came really close. It kept asking if I was sure if I wanted to submit everytime it got to a sensitive step. It would submit but only after a “yes do it”\n\nso which product one shotted it for my family and I? \n\nInstinct. \n\ni wasn’t sure what it submitted is even correct but I went through Korean immigration without a hitch. \n\n@noahrshinn cooked on this one", "name": "Saurabh Suri", "handle": "surim0n", "avatar": "https://pbs.twimg.com/profile_images/1413235403826606087/t3ApjLK9_200x200.jpg", "likes": 56, "rts": 0, "replies": 10, "views": 24469, "ts": 1792483970, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVD0cFNWwAAjupz.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVD0cFIWAAAVnuZ.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVD0cFIWoAA3bat.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.14, "thread": [], "tier": "worth"}, {"id": "2112590277391306929", "url": "https://x.com/dreamlabs_ai/status/2112590277391306929", "text": "Let us know how it goes! We’re working to support the full range of robot developers, including SO-101 users, so any feedback on what works or doesn’t is super helpful.", "name": "Dream Labs", "handle": "dreamlabs_ai", "avatar": "https://pbs.twimg.com/profile_images/2111969228349968384/0P95VSPk_200x200.jpg", "likes": 37, "rts": 2, "replies": 3, "views": 1941, "ts": 1792515746, "media": [], "quote": {"id": "2112588516874236268", "url": "https://x.com/BharatJain/status/2112588516874236268", "text": "Tried out @dreamlabs_ai API on my SO-101 Arm (Mounter on a Rover)\n\nWhile installing the libraries on Jetson, I tested their API (thanks to the $10 welcome credit) on their playground with SO-101 arm. It worked 3/5 times, and was very impressive. \n\nWill be running it on device to see its performance, and share updates. \n\nMy idea is to let ROS2 handle all the low level mapping and navigation, and have VLMs/VLAs carry out semantic specific tasks. \n\nPlease tell me in comments on what should I test the rover + arm setup on? Help me design the benchmark here. \n\nWill keep sharing more updates on building this physical AI Agent", "name": "Bharat Jain", "handle": "BharatJain", "avatar": "https://pbs.twimg.com/profile_images/1883212473051779073/grHB9M_4_200x200.jpg", "likes": 66, "rts": 1, "replies": 6, "views": 4571, "ts": 1792515327, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112585459675406338/vid/avc1/1280x720/0s4SBfEpxRGgEsEz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112585459675406338/vid/avc1/1920x1080/GZJ7CW8INPvnFj7W.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112585459675406338/img/cPV0kGKlUk13haGT.jpg", "dur": 47}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.14, "thread": [], "tier": "worth"}, {"id": "2112628379845599561", "url": "https://x.com/johnrobinsn/status/2112628379845599561", "text": "Phonon - First TTS model IMO to beat kokoro for voice generation quality and performance.  Nice canned voice selection.  License terms for english are Apache 2.0... Other languages are non-commericial (sadly).", "name": "John Robinson", "handle": "johnrobinsn", "avatar": "https://pbs.twimg.com/profile_images/1620478648867233814/uVbZWzAU_200x200.jpg", "likes": 23, "rts": 5, "replies": 3, "views": 1016, "ts": 1792524831, "media": [], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.14, "thread": [], "tier": "worth"}, {"id": "2112308430257995986", "url": "https://x.com/hafuma/status/2112308430257995986", "text": "get out of here with your AI slop", "name": "🤍Hafuma🩵", "handle": "hafuma", "avatar": "https://pbs.twimg.com/profile_images/2073612707203334144/Q0VZNUwm_200x200.jpg", "likes": 14640, "rts": 1399, "replies": 191, "views": 710370, "ts": 1792448549, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112308294635098112/vid/avc1/1278x720/6eSzFg4u5CBoXM-3.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112308294635098112/vid/avc1/1918x1080/57QtoNEDN5N2w8E8.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112308294635098112/img/hHhtg9iC23WTa-2c.jpg", "dur": 25}], "quote": {"id": "2112189582733140096", "url": "https://x.com/CharaspowerAI/status/2112189582733140096", "text": "The hero we didn't know we needed these past few days. 🦸‍♂️🔥\nAbsolute legend.\n\nHaters will say it's AI. 💀😂", "name": "Pierrick Chevallier | IA", "handle": "CharaspowerAI", "avatar": "https://pbs.twimg.com/profile_images/1666802564002893824/5fF909Jc_200x200.jpg", "likes": 29321, "rts": 2997, "replies": 664, "views": 3000340, "ts": 1792420213, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112189530170159104/pu/vid/avc1/640x360/yBAnaQCCpWiV_zBO.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112189530170159104/pu/vid/avc1/1280x720/TtCoPBgwuFujMdPx.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112189530170159104/pu/img/ubtz2olikaUGE2Wq.jpg", "dur": 30}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.13, "thread": [], "tier": "worth"}, {"id": "2112249548991083005", "url": "https://x.com/slash1sol/status/2112249548991083005", "text": "A WORLD MODEL JUST DESIGNED A PHYSICAL OBJECT 100X FASTER AND 150X CHEAPER THAN GPT-6 ASTRA. DOWN TO THE SCREWS\n\n@skyfallai, the neolab from the deep learning pioneers behind Maluuba, just released SKY-001, the first engineering world model.\n\nText prompt or 2D sketch -> it dreams several designs in parallel -> picks the best -> breaks it into thousands of parts -> reassembles a CAD build that opens in Autodesk Fusion.\n\n• Why LLMs lose here\n> They produce 3D shapes that look right and cannot be built, no part hierarchy, no mechanical constraints, no feature tree.\n> Every design step burns tokens, and @spisallyouneed's team measured it: 100x faster and 150x cheaper than GPT-6 Astra on CAD and BIM.\n\n• Where this goes\n> Design is stage one, the goal is an AI general engineer running a company from design to production.\n> Their own org chart already reads 0 employees: an AI CEO, Sky 001 for design, Sky 001 for ops, plugged into AutoCAD, NetSuite, Salesforce and Zendesk.\n\nWorld models imagine and simulate before they act, LLMs guess one token at a time -> for autonomous manufacturing the first one wins.", "name": "slash1s", "handle": "slash1sol", "avatar": "https://pbs.twimg.com/profile_images/1979525426637672448/-H3r1kfe_200x200.jpg", "likes": 87, "rts": 4, "replies": 22, "views": 7772, "ts": 1792434510, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVA0XIYXMAA4EXY.jpg?name=orig"}], "quote": {"id": "2112242023805964327", "url": "https://x.com/spisallyouneed/status/2112242023805964327", "text": "Introducing SKY-001, the first Engineering World Model.\nOn CAD and BIM tasks, it beats GPT-6 Astra and every frontier model we tested:\n\n-> 51-125x faster\n- > 150-210x cheaper\n-> Higher IOU than all frontier models\n\nSKY-001 lets you dream a physical object before you build it.\n\n18 months of work. Built by the team out of Maluuba's deep learning lab (acq. by @MSRResearch).\n\nThe first ‘AI General Engineer’ will be the backbone for Autonomous Manufacturing.", "name": "Sam Pasupalak", "handle": "spisallyouneed", "avatar": "https://pbs.twimg.com/profile_images/1886850141065293824/XbWFJCXo_200x200.jpg", "likes": 15856, "rts": 2304, "replies": 793, "views": 4054470, "ts": 1792432716, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/1280x720/tLYByn7SWDTLqqik.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/3840x2160/QWb8Qsv5A_FWVppa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112239846702129152/img/u4pwfHw4PjnRs2nc.jpg", "dur": 156}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.13, "thread": [], "tier": "worth"}, {"id": "2112540557444870229", "url": "https://x.com/ltx_io/status/2112540557444870229", "text": "We teamed up with @_doubleAI_ to push our already-optimized pipeline further with their Maxwell model. A 5-second 4K clip on 2xB200s: 250s → 134s.\n\nSame quality, no quantization. The update is open source.", "name": "LTX.io", "handle": "ltx_io", "avatar": "https://pbs.twimg.com/profile_images/1981343464068382720/2S5RQyKp_200x200.png", "likes": 43, "rts": 2, "replies": 4, "views": 3696, "ts": 1792503892, "media": [], "quote": {"id": "2112529274984964208", "url": "https://x.com/_doubleAI_/status/2112529274984964208", "text": "1/ Together with @ltx_io, we used Maxwell, our Code Execution Model, to make video generation in LTX-2.5 1.87x faster.\n\nWith Maxwell, generating a five-second 4K clip on 2xB200s went from 250 seconds to only 134. No quantization or loss of quality at all. The code is open source.", "name": "doubleAI", "handle": "_doubleAI_", "avatar": "https://pbs.twimg.com/profile_images/2028457512920367104/dm5x4n83_200x200.png", "likes": 40, "rts": 4, "replies": 5, "views": 5971, "ts": 1792501202, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112525445862150144/vid/avc1/1278x720/UBbjtOdZh2g4jx1b.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112525445862150144/vid/avc1/1918x1080/DCajYItx8wGV8WC-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112525445862150144/img/MrYvi3l3yKG5VV9z.jpg", "dur": 14}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.13, "thread": [], "tier": "worth"}, {"id": "2112632111299469639", "url": "https://x.com/karlarboledas/status/2112632111299469639", "text": "Voxel is about to leave the concept stage.\n\n@roboticscorp droid butler:\n→ Tidies up the house\n→ Finds missing stuff\n→ Fetches things on request\n→ Limited reservations now open\n\nThe real test starts now: how it handles actual homes and everyday mess", "name": "karla", "handle": "karlarboledas", "avatar": "https://pbs.twimg.com/profile_images/2106955765348974592/5Ul1ntrn_200x200.jpg", "likes": 14, "rts": 6, "replies": 5, "views": 814, "ts": 1792525720, "media": [], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1850860, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.13, "thread": [], "tier": "worth"}, {"id": "2112550672298131575", "url": "https://x.com/Quantex0x/status/2112550672298131575", "text": "THIS IS A F*CKING CHEAT CODE FOR QUANTS\n\nMistral just dropped Timestral. #1 on 3 forecasting benchmarks. open weights, runs on a CPU.\n\nOpus 5.5 + REA wired it to 20 open-source repos:\n\n→ ccxt pulls 2,000 BTC 1h candles\n→ Timestral forecasts the next 96 hours\n→ statsforecast builds a random walk to beat\n→ CRPS grades both on data it never saw\n→ the GATE kills it if it loses\n\n#1 on benchmarks. zero proof on your chart.\n\nskill = 1 − CRPS_model / CRPS_random_walk\n\nbelow 0 = a coin flip with 209M parameters.\n\npaste this into Claude Code ↓\n\n\"Install Timestral from timestral github repo. Pull 2,000 BTC 1h candles with ccxt. Forecast 96 steps, score with CRPS against a random walk on 200 unseen windows. Show diffs first.\"\n\nsave it before the next forecast goes viral.", "name": "Quantex", "handle": "Quantex0x", "avatar": "https://pbs.twimg.com/profile_images/2083859192499089408/V6mbHaVO_200x200.jpg", "likes": 27, "rts": 4, "replies": 8, "views": 848, "ts": 1792506304, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112541864653893632/vid/avc1/720x776/4jEBzkqWXGRJmTfA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112541864653893632/vid/avc1/1080x1166/-uPZ7RxUfQSMQ_ll.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112541864653893632/img/ijznyHnxPu3PqavN.jpg", "dur": 22}], "quote": {"id": "2110731912176095700", "url": "https://x.com/velesxbt/status/2110731912176095700", "text": "how do you know a trading strategy still works?\n\nyou don’t. unless you test it.\n\nthis guide turns your AI into a research desk that does it for you: real data, real backtests, stress tests, and a path to your broker https://x.com/i/article/2110377833579061248", "name": "Veles", "handle": "velesxbt", "avatar": "https://pbs.twimg.com/profile_images/2109226539799703552/gTsHS1Ht_200x200.jpg", "likes": 88, "rts": 15, "replies": 13, "views": 154023, "ts": 1792072678, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.13, "thread": [], "tier": "skim"}, {"id": "2112632996272480389", "url": "https://x.com/NewsFromGoogle/status/2112632996272480389", "text": "Doctors spend a significant amount of time during appointments gathering basic information. Google researchers are studying how AMIE, our experimental model system, can help doctors spend more time on collaborative care: addressing patient concerns, identifying symptoms, and figuring out what to do next.", "name": "News from Google", "handle": "NewsFromGoogle", "avatar": "https://pbs.twimg.com/profile_images/1972717909559353344/eMJ6AJ0W_200x200.jpg", "likes": 25, "rts": 3, "replies": 4, "views": 2816, "ts": 1792525931, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112632085735211008/vid/avc1/1280x720/nW9pCvLVOwP6dW_H.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112632085735211008/vid/avc1/3840x2160/q-fcmCocxAYssFcp.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112632085735211008/img/z1W9HayJs7PMsT1B.jpg", "dur": 335}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.13, "thread": [], "tier": "skim"}]);